import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.zip.GZIPOutputStream;

/** Reproducible, synthetic assignment data; no external libraries or downloads. */
public final class DatasetGenerator {
  private DatasetGenerator() {}

  public static void write(
      Path path,
      String type,
      String sizes,
      String encoding,
      String endian,
      String spatial,
      String newline,
      long[] values,
      int bits)
      throws IOException {
    String header =
        "NRRD0005\n# Synthetic data generated by DatasetGenerator\ntype: "
            + type
            + "\ndimension: 3\nsizes: "
            + sizes
            + "\nencoding: "
            + encoding
            + "\n";
    if (bits > 8 && !encoding.equals("ascii")) header += "endian: " + endian + "\n";
    header += spatial + "\n";
    try (OutputStream file = Files.newOutputStream(path)) {
      file.write(header.replace("\n", newline).getBytes(StandardCharsets.US_ASCII));
      try (OutputStream payload = encoding.equals("gzip") ? new GZIPOutputStream(file) : file) {
        for (long value : values) {
          if (encoding.equals("ascii"))
            payload.write((value + "\n").getBytes(StandardCharsets.US_ASCII));
          else
            for (int i = 0; i < bits / 8; i++)
              payload.write(
                  (int) (value >>> (8 * (endian.equals("big") ? bits / 8 - 1 - i : i))) & 255);
        }
      }
    }
  }

  public static void small(Path directory) throws IOException {
    Files.createDirectories(directory);
    long[] coded = new long[8 * 7 * 6];
    for (int z = 0; z < 6; z++)
      for (int y = 0; y < 7; y++)
        for (int x = 0; x < 8; x++) coded[x + 8 * (y + 7 * z)] = x + 10 * y + 100 * z;
    write(
        directory.resolve("coded-u16-rotated.nrrd"),
        "uint16",
        "8 7 6",
        "gzip",
        "little",
        "space: left-posterior-superior\n"
            + "space origin: (10,-20,30)\n"
            + "space directions: (0,2,0) (-1,0,0) (0,0,1.5)\n",
        "\r\n",
        coded,
        16);
    write(
        directory.resolve("unsigned-u32-big.nrrd"),
        "uint32",
        "2 2 2",
        "raw",
        "big",
        "",
        "\n",
        new long[] {0, 1, 2147483647L, 2147483648L, 4294967295L, 65536, 255, 42},
        32);
    write(
        directory.resolve("signed-i16.nrrd"),
        "int16",
        "2 2 2",
        "ascii",
        "little",
        "",
        "\n",
        new long[] {-32768, -1, 0, 1, 32767, 123, -20, 45},
        16);
    write(
        directory.resolve("zero-u8.nrrd"),
        "uint8",
        "4 4 4",
        "raw",
        "little",
        "",
        "\n",
        new long[64],
        8);
    // World positions corresponding to a rectangle and triangle inside the rotated fixture.
    Files.writeString(
        directory.resolve("mixed-planes.csv"),
        "10,-20,33,10,-8,33,4,-20,33,4,-8,33\n9,-14,33,5,-20,33,5,-8,33\n");
  }

  public static void writeBenchmark(Path path) throws IOException {
    if (path.getParent() != null) Files.createDirectories(path.getParent());
    try (OutputStream file = Files.newOutputStream(path)) {
      file.write(
          "NRRD0005\n# Synthetic value: (x+3*y+7*z) modulo 256\ntype: uint8\ndimension: 3\nsizes: 500 500 500\nencoding: gzip\n\n"
              .getBytes(StandardCharsets.US_ASCII));
      try (OutputStream payload = new GZIPOutputStream(file, 65536)) {
        byte[] row = new byte[500];
        for (int z = 0; z < 500; z++)
          for (int y = 0; y < 500; y++) {
            for (int x = 0; x < 500; x++) row[x] = (byte) (x + 3 * y + 7 * z);
            payload.write(row);
          }
      }
    }
  }

  public static void main(String[] args) throws IOException {
    if (args.length == 0) small(Path.of("datasets"));
    else if (args.length == 2 && args[0].equals("--benchmark")) writeBenchmark(Path.of(args[1]));
    else throw new IllegalArgumentException("Usage: DatasetGenerator [--benchmark output.nrrd]");
  }
}
